      "path": "src/host/index.js",
      "content": "/**
 * dsh-clean-desktop-shell — host half (plugin loader entry).
 *
 * Branch 2 (plugin-market distribution): when installed through the DSH
 * plugin market, this host half brings up the Electron shell itself.
 *
 * The shell code is shared with branch 1 (installer) — only the runtime
 * provisioning and launch differ. See runtime.js (provisioning) and
 * icon.js (Windows taskbar icon).
 */
import { spawn } from 'node:child_process'
import { appendFileSync } from 'node:fs'
import { PKG_ROOT, MAIN_JS, dshHome, runtimeRoot, launchLogPath } from './common.js'
import { ensureRuntime } from './runtime.js'
import { ensureRcedit, patchExeIcon } from './icon.js'

// cordis registers the plugin by this name — bundles without an explicit
// `name` export are silently skipped by the dsh loader.
export const name = 'dsh-clean-desktop-shell-pro'

// Disable auto-launch with DSH_SHELL_AUTO_LAUNCH=0.
const AUTO_LAUNCH = process.env.DSH_SHELL_AUTO_LAUNCH !== '0'

/**
 * Hard budget for the taskbar-icon step. It runs before the spawn (Windows
 * locks a running image), so it is on the launch path — but the icon is
 * cosmetic and must never decide when the window appears. Without a budget a
 * stalled rcedit fetch held the first launch for up to the fetchFile default
 * of 600 s; with it, the worst case is 25 s and the usual case is ~0 (the
 * fetch has already finished behind the Electron runtime download).
 */
const ICON_PATCH_DEADLINE_MS = 25000

let launched = false

/**
 * Let a best-effort step run, but never wait longer than `ms` for it. Whatever
 * it was doing keeps running in the background.
 */
function withDeadline(ctx, promise, ms) {
  let timer
  const deadline = new Promise((resolve) => {
    timer = setTimeout(() => {
      ctx.logger.warn(`[clean-desktop-shell] icon step exceeded ${ms} ms — launching without it`)
      resolve()
    }, ms)
    // Do not keep the host process alive just to fire a warning.
    timer.unref?.()
  })
  const settled = promise.then(() => {}, () => {})
  return Promise.race([settled, deadline]).finally(() => clearTimeout(timer))
}

export function apply(ctx) {
  ctx.logger.info('[clean-desktop-shell] mounted (host half)')
  if (!AUTO_LAUNCH) return

  // Runtime preparation is independent of authentication — start it now, but
  // defer the Electron spawn until the launch URL is minted below.
  let runtimeExe = null
  // Kick the (tiny) rcedit fetch off alongside the (large) Electron runtime so
  // the two never serialise; patchExeIcon reuses this same memoised promise.
  void ensureRcedit(ctx)
  const runtimeReady = ensureRuntime(ctx)
    .then(async (exe) => {
      runtimeExe = exe
      await withDeadline(ctx, patchExeIcon(ctx, exe), ICON_PATCH_DEADLINE_MS)
    })
    .catch((err) => {
      reportLaunchFailure(ctx, err)
    })

  // DSH 0.1.2 BrowserAuth: the shell must not start on bare "/" (401). It
  // needs this process's launch URL (?token=…), which the Connection service
  // alone can mint. The service is only reachable from a deferred inject
  // scope — reading ctx.connection in apply() throws "cannot get property
  // without inject" — and the URL is a readiness signal: mint it only after
  // the Loader tree settles, because the port answers 4xx before settlement.
  // Mirror @deepseek-ai/dsh-web-app's announce pattern.
  ctx.inject(['connection'], (connectionCtx) => {
    const launch = () => {
      if (launched) return
      // Only injected services are directly reachable in this scope; the
      // webServer sibling is read through get() (see web-app: it may declare
      // webServer in its row inject, this host does not).
      const webServer = connectionCtx.get('webServer')
      if (!webServer) return
      try {
        const webUrl = `http://127.0.0.1:${String(webServer.port)}`
        // dsh 0.1.2+ mints this process's launch URL through BrowserAuth.
        // Older versions have no BrowserAuth at all — they serve the web root
        // unauthenticated — so a missing mint must NOT stop the launch: the
        // shell just starts with no bootstrap URL, which is exactly the
        // pre-0.1.2 behaviour.
        const mint = connectionCtx.connection.authenticatedUrl
        const launchUrl = typeof mint === 'function' ? mint.call(connectionCtx.connection, webUrl) : null
        void runtimeReady.then(() => {
          if (runtimeExe) launchShell(runtimeExe, connectionCtx, launchUrl)
        })
      } catch (err) {
        reportLaunchFailure(connectionCtx, err)
      }
    }
    // This row's own activation can precede a sibling failure. The tree owns
    // readiness: await the Loader, then re-check that the services still
    // exist — an early shutdown must not spawn a shell for a dead server.
    const settled = connectionCtx.get('loader')?.await()
    if (settled === undefined) launch()
    else {
      void settled.then(() => {
        if (connectionCtx.get('webServer') !== undefined
          && connectionCtx.get('connection') !== undefined) launch()
      }, () => {})
    }
  })
}

/**
 * A provisioning failure used to vanish into ctx.logger — invisible to
 * anyone who is not already tailing the DSH log. That is precisely how the
 * macOS launch bug survived several releases: there was no window, no error
 * dialog, and nothing on disk to send back.
 *
 * Write a diagnostics file next to the runtime and name it in the warning,
 * so a user on an untested platform can hand us something actionable.
 */
function reportLaunchFailure(ctx, err) {
  const message = err?.message ?? String(err)
  ctx.logger.warn(`[clean-desktop-shell] shell launch failed: ${message}`)

  const logPath = launchLogPath()
  const body = [
    `time:     ${new Date().toISOString()}`,
    `platform: ${process.platform} (${process.arch})`,
    `node:     ${process.version}`,
    `dsh home: ${dshHome()}`,
    `runtime:  ${runtimeRoot()}`,
    `entry:    ${MAIN_JS}`,
    `error:    ${message}`,
    '',
    'Things worth checking:',
    '  - first launch downloads the Electron runtime; a blocked network fails here',
    '  - set DSH_SHELL_ELECTRON_DIR to an electron package to skip the download',
    '  - macOS binary: <runtime>/electron-v<ver>/Electron.app/Contents/MacOS/Electron',
    '  - macOS: unsandboxed extractors may drop the executable bit (chmod +x)',
    '',
  ].join('\n')

  try {
    appendFileSync(logPath, body + '\n')
    ctx.logger.warn(`[clean-desktop-shell] diagnostics written to ${logPath}`)
  } catch {
    // Nothing else a headless host process can do.
  }
}

function launchShell(exe, ctx, launchUrl) {
  if (launched) return
  const env = { ...process.env, ELECTRON_RUN_AS_NODE: undefined }
  if (launchUrl) env.DSH_WEB_LAUNCH_URL = launchUrl
  const child = spawn(exe, [MAIN_JS], {
    cwd: PKG_ROOT,
    env,
    stdio: 'ignore',
    windowsHide: false,
  })
  launched = true
  child.on('error', (err) => {
    launched = false
    ctx.logger.warn(`[clean-desktop-shell] shell spawn error: ${err.message}`)
  })
  child.on('exit', (code) => {
    launched = false
    ctx.logger.info(`[clean-desktop-shell] shell exited (${code})`)
  })
}
"
    },
    {
      "path": "electron/main.js",
      "content": "/**
 * dsh-clean-desktop-shell — Electron main process entry.
 *
 * Shell/core decoupling:
 *  - default target: http://127.0.0.1:3080 (existing web profile, zero migration)
 *  - configurable remote target (settings file)
 *  - local backend auto-start on launch; full manual control from the tray
 *
 * The main window is a pure shell — all backend controls live in the tray.
 */
import { app, BrowserWindow, dialog, nativeImage } from 'electron'
import { fileURLToPath } from 'node:url'
import { createMainWindow, reloadWindow } from './window.js'
import { createTray, refreshTrayMenu } from './tray.js'
import { loadConfig, saveConfig, DEFAULT_TARGET_URL } from './config.js'
import { start, stop, getAuthenticatedUrl, getStatus } from './service.js'
import { setupAutoUpdater } from './update.js'
import { shortcutSupported, hasDesktopShortcut, createDesktopShortcut, ensureStartMenuShortcut } from './shortcut.js'
import { APP_USER_MODEL_ID } from './aumid.js'
import { setupCrashGuard } from './crashGuard.js'

const isMac = process.platform === 'darwin'

// Last-resort error capture (userData/shell-crash.log) — install before
// anything else so even early startup failures leave a trace.
setupCrashGuard()

// Windows: pin the AppUserModelId so the taskbar shows our whale icon
// instead of the generic Electron icon. Plugin mode uses a distinct ID
// (see aumid.js) so Windows re-reads the icon instead of serving a
// stale per-AUMID cached one.
if (process.platform === 'win32') {
  app.setAppUserModelId(APP_USER_MODEL_ID)
}

// macOS: a bare runtime has no .app bundle (no icon resource), so set the
// Dock icon at runtime. Unlike Windows there is no per-AUMID taskbar cache
// here — app.dock.setIcon applies directly. Packaged builds already carry
// the icon in their bundle, so skip those.
if (isMac && !app.isPackaged) {
  try {
    const dockIcon = nativeImage.createFromPath(
      fileURLToPath(new URL('../build/icon.png', import.meta.url)),
    )
    if (!dockIcon.isEmpty()) app.dock.setIcon(dockIcon)
  } catch {
    // non-fatal: keep the default icon
  }
}

// Uniform userData across both distribution branches (installer vs
// plugin-market), so config (target URL, backend path, ...) is shared
// no matter how the shell was launched.
app.setName('DSH Clean Desktop Shell')

/** Single instance: a second launch just focuses the existing window. */
const gotLock = app.requestSingleInstanceLock()
if (!gotLock) {
  app.quit()
} else {
  let mainWindow = null
  let tray = null

  // Kick off the local backend as early as possible — in parallel with
  // Electron's own startup and window creation — so the perceived wait is
  // max(electron, backend) instead of electron + backend. start() locates dsh
  // via DSH_BACKEND_DIR / npm global bin / PATH (none of which need app to be
  // ready), and its internal detect() reuses a backend already on the port.
  const earlyBackend = start().catch(() => {})

  app.on('second-instance', () => {
    if (mainWindow) {
      if (mainWindow.isMinimized()) mainWindow.restore()
      mainWindow.focus()
    }
  })

  async function createWindow() {
    const config = loadConfig()
    const target = config.targetUrl || DEFAULT_TARGET_URL
    // In plugin mode the host half (same dsh web process) supplies the real
    // per-process launch URL through DSH_WEB_LAUNCH_URL. In tray-start mode
    // service.start() will surface a fresh one through status changes.
    // Only apply BrowserAuth bootstrap to the local default; remote targets
    // remain the user's own externally-managed surface.
    let isLocalDefault = false
    try {
      isLocalDefault = new URL(target).origin === new URL(DEFAULT_TARGET_URL).origin
    } catch {
      // A malformed configured target must not break window creation, and it
      // must never receive the local launch credential — stay non-local.
    }
    const launchUrl = isLocalDefault ? (getStatus().launchUrl || null) : null

    mainWindow = createMainWindow({ target, launchUrl })
    mainWindow.on('closed', () => {
      mainWindow = null
    })
    mainWindow.on('close', (event) => {
      // Close hides to tray unless we are actually quitting. Read the
      // config fresh so a runtime change to closeToTray takes effect.
      if (!app.isQuitting && loadConfig().closeToTray !== false) {
        event.preventDefault()
        mainWindow?.hide()
      }
    })

    return mainWindow
  }

  /**
   * Launch-time backend detection. Detects whether a local dsh web is
   * already running so the tray and window reflect the real state, but
   * never auto-starts it — starting is a manual action (tray menu or the
   * offline screen button) so it cannot fight an explicit "stop".
   */
  async function bootstrapBackend() {
    const config = loadConfig()
    const target = config.targetUrl || DEFAULT_TARGET_URL
    // Remote targets are the user's own business — never probe local.
    // Origin comparison (not string equality) tolerates trailing slashes
    // and an explicitly written default.
    if (new URL(target).origin !== new URL(DEFAULT_TARGET_URL).origin) return
    // The backend was already kicked off at module scope (see earlyBackend);
    // wait for it (or its failure) and reflect the settled state in the tray.
    await earlyBackend
    // If the early start failed (e.g. dsh was not found on the early PATH),
    // retry once with the configured backend path now that config is ready.
    const st = getStatus().status
    if (st !== 'running' && st !== 'starting') {
      try {
        await start({ backendPath: loadConfig().backendPath })
      } catch {
        // The offline screen still offers the manual start button.
      }
    }
    // Reflect the post-detect state in the tray menu.
    refreshTrayMenu()
  }

  /**
   * First-run desktop shortcut prompt (Windows packaged apps only).
   * Asks once; the tray "create desktop shortcut" item stays available
   * forever, so saying no is never a dead end.
   */
  async function ensureShortcut() {
    if (!shortcutSupported() || loadConfig().shortcutAsked) return
    saveConfig({ ...loadConfig(), shortcutAsked: true })
    if (await hasDesktopShortcut()) return
    const choice = dialog.showMessageBoxSync({
      type: 'question',
      title: '创建桌面快捷方式？',
      message: '是否在桌面创建「DSH Clean Desktop Shell」快捷方式？',
      detail: '选择「跳过」也不影响使用——之后可随时在托盘右键菜单中一键添加。',
      buttons: ['创建', '跳过'],
      defaultId: 0,
      cancelId: 1,
    })
    if (choice === 0) {
      const ok = await createDesktopShortcut()
      if (!ok) {
        dialog.showErrorBox('创建快捷方式失败', '无法在桌面创建快捷方式。可稍后在托盘右键菜单中重试。')
      }
    }
  }

  app.whenReady().then(async () => {
    await createWindow()
    tray = createTray({
      onShow: () => {
        if (!mainWindow) return createWindow()
        mainWindow.show()
        mainWindow.focus()
      },
      onReload: () => {
        if (mainWindow && !mainWindow.isDestroyed()) {
          // Prefer the live launch-token URL from the last shell-started
          // backend; a manual refresh is exactly when a stale config target
          // (or a bare pre-0.1.2 loopback URL) would 401.
          reloadWindow(mainWindow, getAuthenticatedUrl() || loadConfig().targetUrl || DEFAULT_TARGET_URL)
        }
      },
      onQuit: async () => {
        const st = getStatus().status
        if (st === 'running' || st === 'starting') {
          const choice = dialog.showMessageBoxSync({
            type: 'question',
            title: '退出 DeepSeek Harness',
            message: '是否同时关闭后端？',
            detail: '关闭后端会停止本机 dsh web 服务；下次启动会自动重新启动。',
            buttons: ['关闭后端并退出', '仅退出', '取消'],
            defaultId: 0,
            cancelId: 2,
          })
          if (choice === 2) return
          if (choice === 0) {
            try {
              await stop()
            } catch {
              // best-effort
            }
          }
        }
        app.isQuitting = true
        app.quit()
      },
    })

    // Backend bootstrap in background (never delays the window).
    bootstrapBackend().catch(() => {})

    // Windows: wire the auto-updater (downloads new installers silently).
    setupAutoUpdater()

    // Windows: ensure the AUMID-carrying Start-menu shortcut exists so the
    // taskbar button shows our icon (see shortcut.js). Best-effort.
    try {
      ensureStartMenuShortcut()
    } catch {
      // non-fatal
    }

    // First run: offer a desktop shortcut (never nags twice).
    ensureShortcut().catch(() => {})

    app.on('activate', () => {
      if (BrowserWindow.getAllWindows().length === 0) createWindow()
      else mainWindow?.show()
    })
  })

  app.on('window-all-closed', () => {
    // Keep the app alive in the tray (like a normal desktop utility).
    if (!isMac && !app.isQuitting) {
      // do not quit — tray keeps running
    }
  })

  app.on('before-quit', () => {
    app.isQuitting = true
  })
}
"
