      label: '关闭后端',
      enabled: st.status === 'running' || st.status === 'starting',
      click: async () => {
        showProgress({ title: '关闭后端', message: '正在关闭 dsh 后端…' })
        try {
          await stop()
          setProgress({ title: '关闭后端', message: '后端已关闭', state: 'ok' })
